import React, {useState} from 'react'
import { Link, useNavigate } from 'react-router-dom'
import InputForm from "../components/shared/InputForm"
import {useDispatch} from 'react-redux'
import { hideLoading, showLoading } from '../Redux/features/alertSlice'
import axios from 'axios';

const Register = () => {
    const [name, setName] = useState("")
    const [lastName, setlastName] = useState("")
    const [email, setEmail] = useState("")
    const [password, setPassword] = useState("")

    // Hooks:-
    const dispatch = useDispatch()
    const navigate = useNavigate()
    // Form Function :-
    const handleSubmit = async (e) => {
        e.preventDefault()
        try {
            if(!name || !lastName || !email || !password){
                return alert('Please Provide All Fields')
            }
            dispatch(showLoading())
            const {data} = await axios.post('/api/v1/auth/register',{name,lastName,email,password})
            dispatch(hideLoading())
            if(data.success){
                alert('Register Successfully')
                navigate('/dashboard')
            }
        } catch (error) {
            dispatch(hideLoading())
            alert('Invalid Form Details Please Try Again! ')
            console.log(error);
        }
    }
    return (
        <>
            <div className="form-container">
                <form className='card p-2' onSubmit={handleSubmit}>
                    <img src="/assets/images/logo.png" alt="logo" height={200} width={400} />
                    <InputForm 
                    htmlFor="name" 
                    labelText={'Name'} 
                    type={'text'} 
                    value={name} 
                    handleChange={(e) => setName(e.target.value)} 
                    name="name"/>

                   <InputForm 
                    htmlFor="lastName" 
                    labelText={"Last Name"} 
                    type={'text'} 
                    value={lastName} 
                    handleChange={(e) => setlastName(e.target.value)} 
                    name="lastName"/>

                    <InputForm 
                    htmlFor="email" 
                    labelText={"Email"} 
                    type={"email"} 
                    value={email} 
                    handleChange={(e) => setEmail(e.target.value)} 
                    name="email"/>

                    <InputForm 
                    htmlFor="password" 
                    labelText={"Password"} 
                    type={"password"} 
                    value={password} 
                    handleChange={(e) => setPassword(e.target.value)} 
                    name="password"/>

                    <div className="d-flex justify-content-between">
                        <p>Already Register <Link to="/login">Login</Link>{" "}</p>
                    </div>
                    <button type="submit" className="btn btn-primary">
                        Register
                    </button>

                </form>
            </div>
        </>
    )
}

export default Register
